PENAL_QUESTIONS.push({"id":"fcc-penal-609520","sourceQuestionId":"609520","t":"pen-m09","moduleId":"pen-m09","q":"No estelionato contra o INSS, o","o":["beneficiário pratica delito instantâneo de efeitos permanentes, e por isso o prazo prescricional começa a fluir da data do pagamento da primeira parcela.","terceiro e o beneficiário praticam delito permanente, e por isso o prazo prescricional começa a fluir do momento em que o benefício é suspenso ou cancelado.","terceiro pratica delito permanente, e o beneficiário, delito instantâneo, e cada qual terá o início do prazo prescricional em momentos diferentes.","terceiro e o beneficiário praticam delito continuado, e por isso o prazo prescricional começa a fluir do momento em que o benefício é suspenso ou cancelado.","terceiro não beneficiário pratica delito instantâneo de efeitos permanentes, e por isso o prazo prescricional começa a fluir da percepção da primeira prestação do benefício indevido."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - DP (DPE AP)/DPE AP/2018 • TEC 609520","source":"FCC - DP (DPE AP)/DPE AP/2018","subject":"Direito Penal - Do Estelionato e das Outras Fraudes (arts. 171 a 179 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/609520","year":2018,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-497986","sourceQuestionId":"497986","t":"pen-m09","moduleId":"pen-m09","q":"No crime de estelionato contra a previdência social, a devolução da vantagem indevida antes do recebimento da denúncia,","o":["segundo o STJ, pode ser considerada analogicamente ao pagamento do tributo nos crime tributários e significará a extinção da punibilidade.","segundo o STF, pode ser considerada analogicamente à condição prevista na súmula 554 e obstar a ação penal.","segundo o STF, pode ser considerada como falta de justa causa, sem prejuízo da persecução administrativo-fiscal para a cobrança de eventuais juros e multa.","não tem qualquer repercussão na esfera penal por ter o delito em questão natureza previdenciária e expressa previsão legal neste sentido.","somente pode ser considerado como arrependimento posterior."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - JE TJSC/TJ SC/2017 • TEC 497986","source":"FCC - JE TJSC/TJ SC/2017","subject":"Direito Penal - Do Estelionato e das Outras Fraudes (arts. 171 a 179 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/497986","year":2017,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-547820","sourceQuestionId":"547820","t":"pen-m09","moduleId":"pen-m09","q":"Frederico, com o intuito de receber o valor do seguro, escondeu um automóvel de sua propriedade e lavrou um boletim de ocorrência afirmando que havia sido furtado. Tempos depois, Frederico veio a receber o valor pelo sinistro. Nessa situação hipotética, o crime praticado por Frederico é tipificado como","o":["fraude para recebimento indenização ou valor de seguro.","exercício arbitrário das próprias razões.","apropriação indébita.","fraude no comércio.","furto qualificado."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - Of Pol (PC AP)/PC AP/2017 • TEC 547820","source":"FCC - Of Pol (PC AP)/PC AP/2017","subject":"Direito Penal - Do Estelionato e das Outras Fraudes (arts. 171 a 179 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/547820","year":2017,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-358617","sourceQuestionId":"358617","t":"pen-m09","moduleId":"pen-m09","q":"Placídio achou na rua um cartão de crédito e o utilizou para efetuar compras de roupas finas em um estabelecimento comercial. Essa conduta caracterizou o crime de","o":["apropriação indébita.","furto qualificado pela fraude.","estelionato.","extorsão simples.","receptação."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - AJ TRF3/TRF 3/Apoio Especializado/Biblioteconomia/2016 • TEC 358617","source":"FCC - AJ TRF3/TRF 3/Apoio Especializado/Biblioteconomia/2016","subject":"Direito Penal - Do Estelionato e das Outras Fraudes (arts. 171 a 179 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/358617","year":2016,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-410684","sourceQuestionId":"410684","t":"pen-m09","moduleId":"pen-m09","q":"Nos termos preconizados pelo Código Penal, em relação às escusas absolutórias, estará isento de pena","o":["Pedro, co-autor de um crime de furto qualificado juntamente com seu amigo Italo, praticado contra o genitor deste último.","Rodrigo, que invade a chácara de sua família e comete um crime de roubo contra seus ascendentes, subtraindo bens que guarneciam o imóvel.","Paulo, que pratica um crime de furto contra empresa de seu tio.","Micaela, que pratica um crime de estelionato contra seu filho, utilizando os documentos pessoais e cartão de crédito deste para fazer compras em estabelecimentos comerciais de uma determinada cidade.","Flávia, que pratica crime de apropriação indébita contra o seu avô de 70 anos de idade."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - ALegis (ALMS)/ALMS/Jurídico/2016 • TEC 410684","source":"FCC - ALegis (ALMS)/ALMS/Jurídico/2016","subject":"Direito Penal - Do Estelionato e das Outras Fraudes (arts. 171 a 179 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/410684","year":2016,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-300289","sourceQuestionId":"300289","t":"pen-m09","moduleId":"pen-m09","q":"NÃO admite a figura privilegiada, com substituição da pena de reclusão pela de detenção, diminuição de um a dois terços ou aplicação somente da pena de multa, o crime de","o":["furto.","duplicata simulada.","estelionato.","apropriação indébita.","receptação."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - JE TJAL/TJ AL/2015 • TEC 300289","source":"FCC - JE TJAL/TJ AL/2015","subject":"Direito Penal - Do Estelionato e das Outras Fraudes (arts. 171 a 179 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/300289","year":2015,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-300670","sourceQuestionId":"300670","t":"pen-m09","moduleId":"pen-m09","q":"No que concerne aos crimes contra o patrimônio,","o":["configura estelionato o ato de defraudar, mediante alienação não consentida pelo credor ou por outro modo, a garantia pignoratícia, ainda que o agente não tenha a posse do objeto empenhado.","o crime de extorsão alcança a consumação com a efetiva obtenção da vantagem indevida pelo agente, segundo entendimento sumulado do Superior Tribunal de Justiça.","é cabível o perdão judicial no dano culposo.","não tipifica estelionato o ato de dar em locação coisa alheia como própria.","configura concorrência para o crime de furto a contribuição posterior, desde que prometida anteriormente."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - JT TRT15/TRT 15/2015 • TEC 300670","source":"FCC - JT TRT15/TRT 15/2015","subject":"Direito Penal - Do Estelionato e das Outras Fraudes (arts. 171 a 179 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/300670","year":2015,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-209591","sourceQuestionId":"209591","t":"pen-m09","moduleId":"pen-m09","q":"Quanto aos crimes contra o patrimônio, possível assegurar que","o":["é pública condicionada a ação penal no caso de dano cometido por motivo egoístico ou com prejuízo considerável para a vítima.","é causa de aumento da pena no roubo o fato de a vítima estar em serviço de transporte de valores, independentemente de o agente conhecer a circunstância.","é admissível no furto praticado em concurso de pessoas o acréscimo de um terço até metade sobre a pena prevista para a forma simples do delito, por aplicação analógica do disposto para o roubo majorado pela mesma circunstância.","o crime de duplicata simulada é de natureza formal, não exigindo a ocorrência de resultado naturalístico.","cabível o perdão judicial na receptação dolosa simples, se primário o agente e de pequeno valor a coisa."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - JE TJCE/TJ CE/2014 • TEC 209591","source":"FCC - JE TJCE/TJ CE/2014","subject":"Direito Penal - Do Estelionato e das Outras Fraudes (arts. 171 a 179 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/209591","year":2014,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-255005","sourceQuestionId":"255005","t":"pen-m09","moduleId":"pen-m09","q":"Aprovada em Sessão Plenária de 15 de dezembro de 1976, a Súmula 554 do Supremo Tribunal Federal enuncia que O pagamento de cheque emitido sem suficiente previsão de fundos, após o recebimento da denúncia, não obsta o prosseguimento da ação penal. Com o advento da reforma da Parte Geral do Código Penal pela Lei nº 7.209/1984, o sentido normativo dessa súmula passou a ser, no entanto, tensionado por importantes segmentos da doutrina brasileira, notadamente à luz do instituto denominado","o":["desistência voluntária.","arrependimento eficaz.","arrependimento posterior.","crime impossível.","insignificância penal."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - Prom Jus (MPE PA)/MPE PA/2014 • TEC 255005","source":"FCC - Prom Jus (MPE PA)/MPE PA/2014","subject":"Direito Penal - Do Estelionato e das Outras Fraudes (arts. 171 a 179 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/255005","year":2014,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-424483","sourceQuestionId":"424483","t":"pen-m09","moduleId":"pen-m09","q":"No que concerne ao delito de duplicata simulada,","o":["o delito não se caracteriza se a duplicata tiver sido emitida sem correspondência a efetiva prestação de serviço.","é necessária a prova do efetivo prejuízo, por tratar-se de crime de índole material.","é possível a punição pela forma culposa a conduta do agente que, por negligência, causou o extravio de duplicata, possibilitando protesto por terceiro.","é passível de punição o agente que, agindo de boa-fé, tiver emitido o título por erro.","não exclui o crime o ressarcimento do dano através do pagamento da duplicata antes do oferecimento da denúncia."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - NeR (TJ AP)/TJ AP/Outorga de Delegações de Serviços de Notas e de Registros/2011 • TEC 424483","source":"FCC - NeR (TJ AP)/TJ AP/Outorga de Delegações de Serviços de Notas e de Registros/2011","subject":"Direito Penal - Do Estelionato e das Outras Fraudes (arts. 171 a 179 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/424483","year":2011,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-1752346","sourceQuestionId":"1752346","t":"pen-m09","moduleId":"pen-m09","q":"O crime de receptação","o":["de semovente domesticável de produção, ainda que abatido ou dividido em partes, com finalidade de comercialização, é crime contra a fauna e submetido às causas de aumento de pena da Lei no 9.605/1998.","tem a pena aumentada por se tratar de circunstância agravante, quando envolver bens do patrimônio do Estado ou Município.","qualificada demanda atividade comercial regular, vedada essa condição em atividade exercida de forma residencial em razão do princípio da legalidade estrita.","é impunível se o autor do crime de que proveio a coisa é isento de pena, conforme jurisprudência do Superior Tribunal de Justiça.","é punível ainda que o agente tenha apenas influído para que terceiro, de boa-fé, oculte coisa que sabe ser produto de crime."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - DP GO/DPE GO/2021 • TEC 1752346","source":"FCC - DP GO/DPE GO/2021","subject":"Direito Penal - Da Receptação (arts. 180 e 180-A do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1752346","year":2021,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-331110","sourceQuestionId":"331110","t":"pen-m09","moduleId":"pen-m09","q":"No delito de receptação qualificada, a expressão “coisa que deve saber ser produto de crime” possui interpretação do STF no sentido de que","o":["se trata de norma inconstitucional com relação ao preceito secundário, por violar o princípio da proporcionalidade quando comparada à pena prevista para o caput.","se aplica apenas aos casos de dolo eventual, excluindo-se o dolo direto.","abrange igualmente o dolo direto.","configura má utilização da expressão, por ser indicativa de culpa consciente.","impede que no exercício de atividade comercial possa se alegar receptação culposa."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - JE TJSE/TJ SE/2015 • TEC 331110","source":"FCC - JE TJSE/TJ SE/2015","subject":"Direito Penal - Da Receptação (arts. 180 e 180-A do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/331110","year":2015,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-171422","sourceQuestionId":"171422","t":"pen-m09","moduleId":"pen-m09","q":"No que concerne aos crimes contra o patrimônio,","o":["se o agente obteve vantagem ilícita, em prejuízo da vítima, mediante fraude, responderá pelo delito de extorsão.","se, no crime de roubo, em razão da violência empregada pelo agente, a vítima sofreu lesões corporais leves, a pena aumenta-se de um terço.","se configura o crime de receptação mesmo se a coisa tiver sido adquirida pelo agente sabendo ser produto de crime não classificado como de natureza patrimonial.","não comete infração penal quem se apropria de coisa alheia vinda a seu poder por erro, caso fortuito ou força da natureza.","o corte e a subtração de eucaliptos de propriedade alheia não configura, em tese, o crime de furto por não se tratar de bem móvel."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - AJ TRF3/TRF 3/Apoio Especializado/Arquivologia/2014 • TEC 171422","source":"FCC - AJ TRF3/TRF 3/Apoio Especializado/Arquivologia/2014","subject":"Direito Penal - Da Receptação (arts. 180 e 180-A do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/171422","year":2014,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-119843","sourceQuestionId":"119843","t":"pen-m09","moduleId":"pen-m09","q":"Admite realização também sob a modalidade estritamente culposa a figura legal de","o":["dano.","peculato mediante erro de outrem.","furto.","receptação.","favorecimento pessoal."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - NeR (TJ PE)/TJ PE/Provimento/2013 • TEC 119843","source":"FCC - NeR (TJ PE)/TJ PE/Provimento/2013","subject":"Direito Penal - Da Receptação (arts. 180 e 180-A do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/119843","year":2013,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-85076","sourceQuestionId":"85076","t":"pen-m09","moduleId":"pen-m09","q":"No tocante à receptação, correto afirmar que","o":["cabível o perdão judicial na forma culposa do delito.","equiparável a atividade comercial, para efeito de identificação da receptação qualificada, qualquer forma de comércio irregular ou clandestino, excluído o exercido em residência.","a pena deve ser aumentada no caso de bens da União, dos Estados ou dos Municípios, mas não de empresa concessionária de serviços públicos ou sociedade de economia mista.","impunível a infração, se desconhecido ou isento de pena o autor do crime de que proveio a coisa.","inadmissível a imposição exclusiva de pena de multa, ainda que primário o agente e de pequeno valor a coisa receptada."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - JT TRT1/TRT 1/2012 • TEC 85076","source":"FCC - JT TRT1/TRT 1/2012","subject":"Direito Penal - Da Receptação (arts. 180 e 180-A do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/85076","year":2012,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-84837","sourceQuestionId":"84837","t":"pen-m09","moduleId":"pen-m09","q":"Quanto aos crimes contra o patrimônio, é possível afirmar que","o":["a fraude, no furto qualificado, antecede o apossamento da coisa e é a causa de sua entrega ao agente pela vítima.","a receptação qualificada exige que a coisa seja recebida pelo agente no exercício de atividade comercial ou industrial clandestinas.","o delito de dano culposo contra o patrimônio da União é de ação penal pública incondicionada.","é incabível o arrependimento posterior no crime de roubo.","na extorsão o agente busca a obtenção de vantagem ilícita, ainda que não econômica."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - JT TRT1/TRT 1/2011 • TEC 84837","source":"FCC - JT TRT1/TRT 1/2011","subject":"Direito Penal - Da Receptação (arts. 180 e 180-A do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/84837","year":2011,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-2456487","sourceQuestionId":"2456487","t":"pen-m09","moduleId":"pen-m09","q":"Fernando, jovem de 19 anos, aproveitando-se do fato de que seu pai, Ronaldo, com 48 anos, tirava um cochilo durante a tarde, subtraiu de sua carteira, sem que ele percebesse, a quantia de R$ 200,00 em dinheiro, para gastar no sábado à noite com seus amigos do colégio. Diante da situação hipotética apresentada,","o":["Fernando praticou o crime de furto de coisa comum, haja vista a relação familiar entre ele e Ronaldo.","Fernando praticou o crime de furto com abuso de confiança.","Fernando praticou o crime de apropriação indébita.","o crime praticado por Fernando somente se procede mediante representação de Ronaldo.","muito embora o fato seja típico, Fernando, na hipótese, é isento de pena."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - TM (MPE PB)/MPE PB/Sem Especialidade/2023 • TEC 2456487","source":"FCC - TM (MPE PB)/MPE PB/Sem Especialidade/2023","subject":"Direito Penal - Das Disposições Gerais dos Crimes contra o Patrimônio (arts. 181 a 183 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2456487","year":2023,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-2296351","sourceQuestionId":"2296351","t":"pen-m09","moduleId":"pen-m09","q":"Júnior, jovem de 19 anos, decide subtrair a quantia de R$ 2.000,00 de seu pai, Edgar, de 52 anos, aproveitando-se do fato de ele estar, naquela noite, distraído em outro cômodo da residência em que coabitam, assistindo a uma partida de futebol. Diante da situação hipotética acima descrita, e de acordo com o que estabelece o Código Penal, Júnior","o":["não será condenado pela prática de crime, pois é isento de pena, em razão da escusa absolutória.","praticou o crime de furto qualificado por abuso de confiança.","praticou o crime de furto com pena aumentada em razão de ter sido praticado durante o repouso noturno.","praticou o crime de furto de coisa comum, por ser da mesma família que a vítima.","por ser primário, e de pequeno valor a coisa furtada, poderá ter a sua pena substituída somente por multa."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - TJ TRT5/TRT 5/Administrativa/Agente da Policia Judicial/2022 • TEC 2296351","source":"FCC - TJ TRT5/TRT 5/Administrativa/Agente da Policia Judicial/2022","subject":"Direito Penal - Das Disposições Gerais dos Crimes contra o Patrimônio (arts. 181 a 183 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2296351","year":2022,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-1071516","sourceQuestionId":"1071516","t":"pen-m09","moduleId":"pen-m09","q":"Considere as seguintes situações hipotéticas de crimes de furto e roubo: I. Paulo, durante o período noturno, ingressou no quarto do seu pai, João, de 70 anos de idade, e subtraiu a quantia de R$ 3.000,00 em dinheiro que estava ocultada no guarda-roupas. II. Mariano, policial militar, apontou a arma de fogo para a esposa Rita, com quem é regularmente casado e convive na mesma residência, e subtraiu diversas joias em ouro pertencentes a ela, fugindo em seguida. III. Os irmãos Michael e Josué estavam em uma festa na cidade de São Paulo, que acontecia em uma casa noturna. No curso da festa, Michael saiu da casa noturna e furtou o veículo de propriedade de Josué, entregando o bem para um comparsa, retornando para a festa logo em seguida. IV. Davi, em comparsaria com Felício, praticou furto noturno, mediante arrombamento, contra o estabelecimento comercial de propriedade de Rodolfo, filho legítimo de Davi. De acordo com o Código Penal, o Ministério Público poderá ajuizar ação penal pública incondicionada, e postular a aplicação das sanções previstas, contra Mariano","o":["Paulo, Davi e Felício.","Michael e Davi.","Paulo e Michael.","Paulo e Felício.","Michael e Felício."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - AJ TRF3/TRF 3/Judiciária/\"Sem Especialidade\"/2019 • TEC 1071516","source":"FCC - AJ TRF3/TRF 3/Judiciária/\"Sem Especialidade\"/2019","subject":"Direito Penal - Das Disposições Gerais dos Crimes contra o Patrimônio (arts. 181 a 183 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1071516","year":2019,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-98075","sourceQuestionId":"98075","t":"pen-m09","moduleId":"pen-m09","q":"Considere as seguintes assertivas com relação aos crimes contra o patrimônio, de acordo com o Código Penal: I. É isento de pena quem comete crime de furto em prejuízo de ascendente com 60 anos de idade. II. Somente se procede mediante representação, se o agente pratica crime de estelionato em prejuízo de irmão. III. É isento de pena quem comete crime de extorsão contra cônjuge na constância da sociedade conjugal. Está correto que se afirma SOMENTE em","o":["II.","I e II.","I e III.","II e III.","III."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - AJ TRE AP/TRE AP/Administrativa/2011 • TEC 98075","source":"FCC - AJ TRE AP/TRE AP/Administrativa/2011","subject":"Direito Penal - Das Disposições Gerais dos Crimes contra o Patrimônio (arts. 181 a 183 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/98075","year":2011,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra o patrimônio.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-3937811","sourceQuestionId":"3937811","t":"pen-m09","moduleId":"pen-m09","q":"Sobre os crimes contra o patrimônio, considere: I. O furto qualificado pelo concurso de agentes com adolescente de 17 anos não atrai a corrupção de menores, sob pena de configurar bis in idem. II. O furto de fios utilizados para fornecimento de energia elétrica avaliados em R$ 855,00 cometido por agente primário não impede o reconhecimento da figura privilegiada. III. No curso de um crime de roubo o agente solicita para a vítima que desligue a localização e o aparelho celular, subtraindo apenas o veículo. No caso, deve o agente responder também pelo crime de extorsão. IV. Conforme entendimento do Superior Tribunal de Justiça, é inviável a incidência do privilégio na hipótese de furto qualificado pelo abuso de confiança. Está correto o que se afirma APENAS em","o":["I e IV.","I, II e IV.","III e IV.","II e III.","II e IV."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - DP MA/DPE MA/2026 • TEC 3937811","source":"FCC - DP MA/DPE MA/2026","subject":"Direito Penal - Questões Mescladas sobre Crimes Contra o Patrimônio (arts. 155 a 183 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3937811","year":2026,"caderno":4,"classificationReason":"Crimes contra o patrimônio expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-789042","sourceQuestionId":"789042","t":"pen-m09","moduleId":"pen-m09","q":"No que se refere aos crimes contra o patrimônio,","o":["diminui-se a pena de um a dois terços, na apropriação indébita previdenciária, se o agente, voluntariamente, confessa, declara e efetua o pagamento das contribuições e importâncias devidas à Previdência Social.","todas as hipóteses de furto são de ação penal pública, em nenhuma delas procedendo-se mediante representação.","se o crime for de extorsão mediante sequestro e for cometido em concurso, o concorrente que o denunciar à autoridade, facilitando a libertação do sequestrado, terá extinta sua punibilidade.","tratando-se de esbulho possessório, se a propriedade for particular, havendo ou não emprego de violência, somente se procede mediante queixa.","no crime de furto, se o criminoso é primário, e é de pequeno valor a coisa furtada, o juiz pode substituir a pena de reclusão pela de detenção, diminuí-la de um a dois terços, ou aplicar somente a pena de multa."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019 • TEC 789042","source":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019","subject":"Direito Penal - Questões Mescladas sobre Crimes Contra o Patrimônio (arts. 155 a 183 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/789042","year":2019,"caderno":4,"classificationReason":"Crimes contra o patrimônio expressamente previstos.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-1992311","sourceQuestionId":"1992311","t":"pen-m09","moduleId":"pen-m09","q":"Em relação aos crimes contra o patrimônio, correto afirmar que","o":["a coisa abandonada pode ser objeto material do crime de furto.","a extorsão mediante sequestro atinge a consumação com a efetiva obtenção da vantagem desejada pelo agente.","o emprego de arma não qualifica o delito de extorsão.","privada a ação penal no crime de dano qualificado por motivo egoístico ou com prejuízo considerável para a vítima.","cabível o perdão judicial na receptação dolosa simples."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 9: Crimes contra o patrimônio.","r":"FCC - Prom Jus (MPE AL)/MPE AL/1ª Entrância/2012 • TEC 1992311","source":"FCC - Prom Jus (MPE AL)/MPE AL/1ª Entrância/2012","subject":"Direito Penal - Questões Mescladas sobre Crimes Contra o Patrimônio (arts. 155 a 183 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1992311","year":2012,"caderno":4,"classificationReason":"Crimes contra o patrimônio expressamente previstos.","update":"Lei 15.397/2026 alterou penas e figuras de furto, roubo, estelionato e receptação. Preserve o gabarito histórico, mas resolva pela redação vigente.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-3883963","sourceQuestionId":"3883963","t":"pen-m11","moduleId":"pen-m11","q":"Rafael foi com seus amigos a uma festa privada em que era proibida a entrada de menor de 18 anos. Durante a festa, Rafael viu Manuela dançando e aproximou-se dela. Eles começaram a conversar e ele, fingindo ser dono de uma agência de modelo, perguntou se Manuela era maior de idade e se gostaria de trabalhar com ele. Ela respondeu que sim. De repente, no meio da conversa, Rafael deu um beijo na boca de Manuela e passou a mão em suas nádegas, sem pedir seu consentimento. Manuela ficou assustada e suas amigas chamaram o segurança. Quando o segurança verificou que Manuela tinha 13 anos e que o documento utilizado para entrar no evento era falso, todos foram conduzidos à delegacia. Com base nos fatos descritos, a conduta de Rafael configura-se como","o":["estupro de vulnerável.","violação sexual mediante fraude.","importunação sexual.","constrangimento ilegal.","satisfação de lascívia mediante presença de criança ou adolescente."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - DP MT/DPE MT/2026 • TEC 3883963","source":"FCC - DP MT/DPE MT/2026","subject":"Direito Penal - Dos Crimes contra a Liberdade Sexual e da Exposição da Intimidade Sexual (arts. 213 a 216-B do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3883963","year":2026,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3940990","sourceQuestionId":"3940990","t":"pen-m11","moduleId":"pen-m11","q":"Marina, aprovada no concurso da ALEMS, no ambiente de trabalho, passou a receber, de seu superior hierárquico comentários de cunho sexual que a constrangiam com o intuito de obter vantagem ou favorecimento sexual, valendo-se da condição de superior hierárquico inerente ao exercício do emprego, cargo ou função. Neste caso, o superior hierárquico, em tese, cometeu o crime de","o":["importunação sexual em concurso material com violação sexual mediante fraude.","estupro.","importunação sexual.","violação sexual mediante fraude.","assédio sexual."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - TLegis (ALMS)/ALMS/Polícia Legislativa/2026 • TEC 3940990","source":"FCC - TLegis (ALMS)/ALMS/Polícia Legislativa/2026","subject":"Direito Penal - Dos Crimes contra a Liberdade Sexual e da Exposição da Intimidade Sexual (arts. 213 a 216-B do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3940990","year":2026,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3956077","sourceQuestionId":"3956077","t":"pen-m11","moduleId":"pen-m11","q":"Paulo foi denunciado como incurso no delito de importunação sexual (artigo 215-A, do Código Penal) porque, no dia 05 de março de 2026, teria sido flagrado se masturbando, dentro da cabine do banheiro masculino da loja onde trabalha, por uma funcionária que era sua subordinada. A funcionária contou que estava na área de acesso restrito quando ouviu um barulho vindo de dentro do banheiro masculino. Decidiu entrar ali para ver o que estava acontecendo e quando abriu a porta de uma das cabines do banheiro flagrou seu gerente Paulo se masturbando. Como não havia mais ninguém na loja, a funcionária temerosa ligou para a polícia. Comprovados os fatos relatados, a juíza condenou Paulo nos termos da denúncia. A decisão está ERRADA, porque a conduta de Paulo","o":["configura crime de ato obsceno.","configura crime de assédio sexual.","é atípica porque a conduta não foi direcionada à funcionária.","é conduta típica e antijurídica, excluindo-se a culpabilidade por erro de proibição, pois Paulo acreditou estar sozinho.","é atípica porque não houve contato físico entre Paulo e a funcionária."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - DP BA/DPE BA/2026 • TEC 3956077","source":"FCC - DP BA/DPE BA/2026","subject":"Direito Penal - Dos Crimes contra a Liberdade Sexual e da Exposição da Intimidade Sexual (arts. 213 a 216-B do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3956077","year":2026,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3986889","sourceQuestionId":"3986889","t":"pen-m11","moduleId":"pen-m11","q":"Eduardo é proprietário e chef de cozinha de um respeitado restaurante na cidade de Maceió/AL. Na festa de final de ano, durante amigo secreto, Eduardo presenteia a hostess do seu estabelecimento, Rosana, sua amiga secreta, com um conjunto de lingeries e a convida após o evento a passar um final de semana em sua casa em São Miguel dos Milagres. Rosana recusa o convite e Eduardo, inconformado, passa a perseguir Rosana durante o trabalho, reiterando por diversas vezes o convite rejeitado, elogiando-a com comentários de cunho sexual, ameaçando-a, inclusive, de demissão caso não fosse correspondido. Nos termos preconizados pelo Código Penal, Eduardo cometeu crime, em tese, de","o":["rufianismo.","violação sexual mediante fraude.","importunação sexual.","assédio sexual.","sedução."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - Ana (MPE AL)/MPE AL/Jurídica/2026 • TEC 3986889","source":"FCC - Ana (MPE AL)/MPE AL/Jurídica/2026","subject":"Direito Penal - Dos Crimes contra a Liberdade Sexual e da Exposição da Intimidade Sexual (arts. 213 a 216-B do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3986889","year":2026,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2488277","sourceQuestionId":"2488277","t":"pen-m11","moduleId":"pen-m11","q":"Penélope, mãe do adolescente Hermes, de 16 anos de idade, procurou a polícia para relatar que seu filho deixou destravados aplicativos de mensagens de suas redes sociais em seu celular, ocasião em que encontrou conversas entre seu filho Hermes e o professor dele, Dionísio. Nessas conversas, o professor insinua que irá pagar motéis para se encontrar com o adolescente, propondo, ainda, melhorar suas notas escolares. No caso narrado, Dionísio praticou, em tese, o crime de","o":["violação sexual mediante fraude.","registro não autorizado da intimidade sexual.","assédio sexual.","estupro tentado.","importunação sexual."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488277","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Penal - Dos Crimes contra a Liberdade Sexual e da Exposição da Intimidade Sexual (arts. 213 a 216-B do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488277","year":2025,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-2348511","sourceQuestionId":"2348511","t":"pen-m11","moduleId":"pen-m11","q":"Marina pedalava sua bicicleta em via pública, ocasião em que Carlos, pilotando sua motocicleta no mesmo local, aproximou-se da ciclista. Aproveitando-se da distração de Marina, Carlos passou sua mão nas nádegas da vítima, empreendendo, na sequência, fuga do local. Diante da situação hipotética acima mencionada, Carlos praticou em tese o crime de","o":["importunação sexual.","assédio sexual.","tentativa de estupro.","estupro consumado.","estupro privilegiado."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - Sold (PM BA)/PM BA/2023 • TEC 2348511","source":"FCC - Sold (PM BA)/PM BA/2023","subject":"Direito Penal - Dos Crimes contra a Liberdade Sexual e da Exposição da Intimidade Sexual (arts. 213 a 216-B do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2348511","year":2023,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-2456488","sourceQuestionId":"2456488","t":"pen-m11","moduleId":"pen-m11","q":"Aquele que constranger alguém com o intuito de obter vantagem ou favorecimento sexual, prevalecendo-se o agente da sua condição de superior hierárquico ou ascendência inerentes ao exercício de emprego, cargo ou função, pratica, em tese, segundo o Código Penal, o crime de","o":["violação sexual mediante fraude.","estupro de vulnerável.","importunação sexual.","assédio sexual.","estupro."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - TM (MPE PB)/MPE PB/Sem Especialidade/2023 • TEC 2456488","source":"FCC - TM (MPE PB)/MPE PB/Sem Especialidade/2023","subject":"Direito Penal - Dos Crimes contra a Liberdade Sexual e da Exposição da Intimidade Sexual (arts. 213 a 216-B do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2456488","year":2023,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-2152405","sourceQuestionId":"2152405","t":"pen-m11","moduleId":"pen-m11","q":"Sobre os crimes contra a dignidade sexual:","o":["O crime de atentado violento ao pudor pressupõe representação da vítima, que pode ser suprida pelos responsáveis em caso de menoridade.","A violação sexual mediante fraude consiste em seduzir mulher virgem, menor de dezoito anos e maior de quatorze, e ter com ela conjunção carnal, aproveitando-se de sua inexperiência ou justificável confiança.","O crime de estupro, previsto no artigo 213, admite tentativa.","Configura crime de assédio sexual constranger alguém com o intuito de obter vantagem ou favorecimento sexual mediante ameaça.","A conduta de montar uma fotografia com o fim de incluir pessoa em cena de nudez não configura crime."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - AJ (TJ CE)/TJ CE/Judiciária/\"Sem Especialidade\"/2022 • TEC 2152405","source":"FCC - AJ (TJ CE)/TJ CE/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Penal - Dos Crimes contra a Liberdade Sexual e da Exposição da Intimidade Sexual (arts. 213 a 216-B do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2152405","year":2022,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-1982989","sourceQuestionId":"1982989","t":"pen-m11","moduleId":"pen-m11","q":"Sobre as causas de aumento previstas na parte especial do Código Penal, é correto afirmar que","o":["a pena será aumentada até um terço se na associação criminosa houver a participação de adolescente.","a sanção será em dobro se a vítima do crime de estelionato for idosa.","no crime de perseguição a pena é aumentada de metade se for cometido contra pessoa com deficiência.","a pena, exceto no caso de difamação, aumenta em um terço se o crime contra a honra for praticado contra pessoa maior de 60 anos.","no crime de importunação sexual a pena é aumentada de metade se o agente é empregador da vítima."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - DP AM/DPE AM/2021 • TEC 1982989","source":"FCC - DP AM/DPE AM/2021","subject":"Direito Penal - Dos Crimes contra a Liberdade Sexual e da Exposição da Intimidade Sexual (arts. 213 a 216-B do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1982989","year":2021,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-1005156","sourceQuestionId":"1005156","t":"pen-m11","moduleId":"pen-m11","q":"De acordo com o ordenamento jurídico e o posicionamento dos tribunais superiores sobre os crimes contra a dignidade sexual,","o":["a prática de passar as mãos nas coxas e seios da vítima menor de 14 anos, por dentro de sua roupa, não pode ser tipificado como crime de estupro de vulnerável (art. 217-A do Código Penal), haja vista que não houve a conjunção carnal.","o estupro (art. 213 do Código Penal), com redação dada pela Lei no 12.015/2009, é tipo penal misto alternativo. Logo, se o agente, no mesmo contexto fático, pratica conjunção carnal e outro ato libidinoso contra uma só vítima, pratica um só crime do art. 213 do Código Penal.","a conduta consistente em manter casa para fins libidinosos é suficiente para a caracterização do crime tipificado no art. 229 do Código Penal, sendo desnecessário, para a configuração do delito, que haja exploração sexual, assim entendidacomo a violação à liberdade das pessoas que ali exercem a mercancia carnal.","somente no crime de estupro, praticado mediante violência real, é que a ação penal é pública incondicionada. Nas demais modalidades de violência, trata-se de crime de ação penal condicionada a representação.","segundo a legislação brasileira, o estupro coletivo é aquele praticado mediante concurso de três ou mais pessoas."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - Prom Jus (MPE MT)/MPE MT/2019 • TEC 1005156","source":"FCC - Prom Jus (MPE MT)/MPE MT/2019","subject":"Direito Penal - Dos Crimes contra a Liberdade Sexual e da Exposição da Intimidade Sexual (arts. 213 a 216-B do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1005156","year":2019,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-1021086","sourceQuestionId":"1021086","t":"pen-m11","moduleId":"pen-m11","q":"Em 2009, houve uma alteração no Código Penal em relação aos crimes sexuais, sendo que o título passou a ser Dos crimes contra a dignidade sexual e o capítulo I passou a ser chamado Dos crimes contra a liberdade sexual, trazendo, dentre outras, a seguinte alteração:","o":["com a mudança da lei, os homens passaram a ser vítimas do crime intitulado como Atentado violento ao pudor.","antes da mudança da lei, as mulheres não podiam ser vítimas do crime intitulado como Atentado violento ao pudor.","atualmente no conceito de estupro está incluída a conjunção carnal e os outros atos libidinosos.","com a mudança da legislação passou a existir o crime de atentado ao pudor mediante fraude, no qual a vítima só pode ser mulher honesta.","a conjunção carnal não é considerada um ato libidinoso."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - Per (DPT BA)/DPT BA/Médico Legal/2014 • TEC 1021086","source":"FCC - Per (DPT BA)/DPT BA/Médico Legal/2014","subject":"Direito Penal - Dos Crimes contra a Liberdade Sexual e da Exposição da Intimidade Sexual (arts. 213 a 216-B do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1021086","year":2014,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-2637153","sourceQuestionId":"2637153","t":"pen-m11","moduleId":"pen-m11","q":"Em 2009 houve uma mudança no Código Penal no capítulo referente aos crimes contra a dignidade sexual. Entretanto, os conceitos médico-legais não sofreram alterações. Considere as afirmativas abaixo. I. Atualmente só é considerado estupro a conjunção carnal não consensual, sendo as demais formas de relação sexual não consensual classificadas como atentado violento ao pudor. II. Conjunção carnal é a introdução, completa ou não, do pênis na vagina, com ou sem ejaculação. III. O estupro é um crime que deixa vestígios, sendo indispensável a realização do exame pericial. Está correto o que se afirma em","o":["I, II e III.","I e III, apenas.","I e II, apenas.","II e III, apenas.","II, apenas."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - AJ (TJ AP)/TJ AP/Apoio Especializado/Perícia Médica/2014 • TEC 2637153","source":"FCC - AJ (TJ AP)/TJ AP/Apoio Especializado/Perícia Médica/2014","subject":"Direito Penal - Dos Crimes contra a Liberdade Sexual e da Exposição da Intimidade Sexual (arts. 213 a 216-B do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2637153","year":2014,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-121485","sourceQuestionId":"121485","t":"pen-m11","moduleId":"pen-m11","q":"Nos crimes contra a liberdade sexual, NÃO constitui causa de aumento da pena a circunstância de","o":["resultar gravidez.","o agente ser casado.","o agente ser empregador da vítima.","o crime ser cometido com concurso de duas ou mais pessoas.","o agente transmitir doença sexualmente transmissível de que sabe ser portador."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - JE TJPE/TJ PE/2011 • TEC 121485","source":"FCC - JE TJPE/TJ PE/2011","subject":"Direito Penal - Dos Crimes contra a Liberdade Sexual e da Exposição da Intimidade Sexual (arts. 213 a 216-B do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/121485","year":2011,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-2456250","sourceQuestionId":"2456250","t":"pen-m11","moduleId":"pen-m11","q":"A prática do ato libidinoso sem a anuência de alguém com o objetivo de satisfazer-se é considerado crime e passível de reclusão de 1 a 5 anos. A pena é acrescida de 1/3 a 2/3 quando o crime é praticado para controlar o comportamento social ou sexual da vítima. Esse tipo de agressão é denominado","o":["estupro corretivo.","agravo sexual.","estupro coletivo.","assédio sexual.","stalker."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - AM (MPE PB)/MPE PB/Assistência Social/2023 • TEC 2456250","source":"FCC - AM (MPE PB)/MPE PB/Assistência Social/2023","subject":"Direito Penal - Dos Crimes Sexuais contra Vulnerável (arts. 217-A a 226 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2456250","year":2023,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-1981291","sourceQuestionId":"1981291","t":"pen-m11","moduleId":"pen-m11","q":"O crime de estupro de vulnerável, conforme o Superior Tribunal de Justiça,","o":["não é considerado hediondo diante da legalidade estrita para tal configuração.","pode ser considerado atípico diante de eventual consentimento da vítima.","exige a fixação de regime inicial fechado em razão do quantum de pena previsto.","impede a responsabilização do agente na qualidade de partícipe.","prescinde de contato físico direto do réu com a vítima."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - DP PB/DPE PB/2022 • TEC 1981291","source":"FCC - DP PB/DPE PB/2022","subject":"Direito Penal - Dos Crimes Sexuais contra Vulnerável (arts. 217-A a 226 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1981291","year":2022,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-1684628","sourceQuestionId":"1684628","t":"pen-m11","moduleId":"pen-m11","q":"Sobre o crime de divulgação de cena de estupro ou de cena de estupro de vulnerável, de cena de sexo ou de pornografia, é correto afirmar que","o":["se consuma com a invasão de dispositivo informático de uso alheio para obter foto ou vídeo íntimo com nudez da vítima.","sua tipicidade depende de divulgação de cena de sexo com violência; do contrário, configura o crime de difamação.","quando a vítima for mulher, seu consentimento é incapaz de excluir a ilicitude da conduta, dada a especial proteção de gênero prevista pela norma.","a prévia relação íntima de afeto, por constituir elementar do tipo, não pode incidir como motivação para aumento de pena.","o especial fim de vingança ou humilhação é causa de aumento de pena de um terço a dois terços."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - DP BA/DPE BA/2021 • TEC 1684628","source":"FCC - DP BA/DPE BA/2021","subject":"Direito Penal - Dos Crimes Sexuais contra Vulnerável (arts. 217-A a 226 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1684628","year":2021,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-840027","sourceQuestionId":"840027","t":"pen-m11","moduleId":"pen-m11","q":"No dia 23 de abril de 2013, Jailson, aproveitando que sua esposa havia saído de casa para fazer compras, decidiu ir até o quarto de sua enteada Jéssica, que à época contava com 19 anos de idade. Ao perceber que Jéssica estava dormindo, Jailson se aproximou de sua cama, apalpou seus seios e começou a acariciar sua vagina por dentro da calcinha. Ocorre que, nesse momento, o irmão de Jéssica chegou à casa e, ao presenciar a cena, começou a gritar, momento em que Jailson se afastou da jovem e fugiu. O tipo penal em que incorreu Jailson, sem analisar se o delito teria se dado na forma consumada ou tentada, é:","o":["Estupro (art. 213, caput, do CP).","Estupro de vulnerável (art. 217-A, §1o, do CP).","Violação sexual mediante fraude (art. 215, caput, do CP).","Importunação sexual (art. 215-A, do CP).","Constrangimento ilegal (art. 146, caput, do CP)."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - DP SP/DPE SP/2019 • TEC 840027","source":"FCC - DP SP/DPE SP/2019","subject":"Direito Penal - Dos Crimes Sexuais contra Vulnerável (arts. 217-A a 226 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/840027","year":2019,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-714200","sourceQuestionId":"714200","t":"pen-m11","moduleId":"pen-m11","q":"João e Maria, com 18 e 13 anos de idade, respectivamente, iniciaram relacionamento amoroso que culminou em relações sexuais consensuais. Inconformado com o fato, o pai de Maria procura a autoridade policial e solicita a instauração de inquérito policial contra João por entender que sua filha está sendo vítima de abuso sexual. No âmbito do direito penal,","o":["João praticou o crime de satisfação de lascívia contra pessoa menor de 14 anos.","a existência de relacionamento amoroso entre o casal torna a conduta de João atípica.","o consentimento de Maria à conjunção carnal torna o crime de estupro impossível.","comprovado que Maria tinha experiência sexual anterior, João praticou o crime de estupro privilegiado.","João praticou o crime de estupro de vulnerável."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - Prom Jus (MPE PB)/MPE PB/2018 • TEC 714200","source":"FCC - Prom Jus (MPE PB)/MPE PB/2018","subject":"Direito Penal - Dos Crimes Sexuais contra Vulnerável (arts. 217-A a 226 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/714200","year":2018,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-541439","sourceQuestionId":"541439","t":"pen-m11","moduleId":"pen-m11","q":"A mídia noticiou que um médico endoscopista foi flagrado em sua clínica tendo relação sexual com uma paciente de 35 anos enquanto ela estava sob efeito do sedativo utilizado para o exame de endoscopia digestiva alta. Desse modo, o médico foi acusado de ter cometido crime de","o":["estupro.","atentado violento do pudor.","estupro de vulnerável.","sedução.","assédio sexual."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - PML (PCA AP)/PCA AP/\"Sem Área\"/2017 • TEC 541439","source":"FCC - PML (PCA AP)/PCA AP/\"Sem Área\"/2017","subject":"Direito Penal - Dos Crimes Sexuais contra Vulnerável (arts. 217-A a 226 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/541439","year":2017,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-118106","sourceQuestionId":"118106","t":"pen-m11","moduleId":"pen-m11","q":"Constitui crime contra a dignidade sexual praticar conjunção carnal ou outro ato libidinoso, sem violência ou grave ameaça, com alguém não deficiente mental ou enfermo","o":["menor de dezoito anos e maior de dezesseis anos.","menor de dezoito anos e maior de quatorze anos em situação de prostituição.","menor de vinte e um anos e maior de quatorze anos em situação de prostituição.","em situação de prostituição, independentemente da idade.","menor de dezesseis anos e maior de quatorze anos."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - DP AM/DPE AM/2013 • TEC 118106","source":"FCC - DP AM/DPE AM/2013","subject":"Direito Penal - Dos Crimes Sexuais contra Vulnerável (arts. 217-A a 226 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/118106","year":2013,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-121277","sourceQuestionId":"121277","t":"pen-m11","moduleId":"pen-m11","q":"No crime de favorecimento da prostituição ou outra forma de exploração sexual de vulnerável,","o":["punível quem praticar conjunção carnal com alguém menor de dezoito e maior de doze anos em situação de prostituição.","punível o proprietário do local em que se verifiquem as práticas, ainda que delas não tenha conhecimento.","o sujeito passivo só pode ser pessoa menor de dezoito anos.","a pena é aumentada de um terço, se praticado com o fim de obter vantagem econômica.","constitui efeito obrigatório da condenação a cassação da licença de localização e de funcionamento do estabelecimento."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - JE TJPE/TJ PE/2013 • TEC 121277","source":"FCC - JE TJPE/TJ PE/2013","subject":"Direito Penal - Dos Crimes Sexuais contra Vulnerável (arts. 217-A a 226 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/121277","year":2013,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-713369","sourceQuestionId":"713369","t":"pen-m11","moduleId":"pen-m11","q":"O estupro de vulnerável pressupõe que","o":["a vítima seja menor de 14 anos e do sexo feminino.","a violência seja real e a vítima menor de 14 anos.","haja conjunção carnal e a vítima seja menor de 12 anos.","a vítima seja menor de 12 anos, independentemente do sexo e da natureza da violência, desde que haja conjunção carnal.","a vítima seja menor de 14 anos e haja conjunção carnal ou outro ato libidinoso."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 11: Crimes contra a dignidade sexual.","r":"FCC - Prom Jus (MPE CE)/MPE CE/2011 • TEC 713369","source":"FCC - Prom Jus (MPE CE)/MPE CE/2011","subject":"Direito Penal - Dos Crimes Sexuais contra Vulnerável (arts. 217-A a 226 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/713369","year":2011,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a dignidade sexual.","update":"Leis 15.280/2025 e 15.353/2026 agravaram penas e positivaram a presunção absoluta de vulnerabilidade; confira a redação atual.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-943345","sourceQuestionId":"943345","t":"pen-m10","moduleId":"pen-m10","q":"Ronaldo, dono de um minimercado situado na cidade de Florianópolis, recebeu em seu estabelecimento, de boa-fé e como verdadeira, uma nota de R$ 100,00 de um cliente para pagamento de uma compra. No dia seguinte, Ronaldo tomou conhecimento de que a nota recebida é falsa, mas, mesmo assim, ele a restituiu à circulação. Neste caso, Ronaldo","o":["não cometeu qualquer infração penal.","cometeu crime de moeda falsa e está sujeito à pena de detenção, de 6 meses a 2 anos, e multa.","cometeu crime de moeda falsa e está sujeito à pena de reclusão, de 3 a 12 anos, e multa, sem qualquer benefício.","cometeu crime de moeda falsa e está sujeito à pena de reclusão, de 3 a 12 anos, e multa, que será reduzida de 1/6 a 1/3 em razão da boa fé quando do recebimento da cédula.","cometeu crime de moeda falsa e está sujeito à pena de reclusão, de 3 a 12 anos, e multa, mas o Magistrado poderá lhe conceder o perdão judicial."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2019 • TEC 943345","source":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2019","subject":"Direito Penal - Moeda Falsa (art. 289 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/943345","year":2019,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-212439","sourceQuestionId":"212439","t":"pen-m10","moduleId":"pen-m10","q":"A respeito do crime de moeda falsa, tal como tipificado no Código Penal (art. 289),","o":["há uma hipótese de conduta culposa de menor potencial ofensivo.","há uma hipótese de conduta dolosa de menor potencial ofensivo.","há uma hipótese de conduta culposa, mas nenhuma de menor potencial ofensivo.","todas as hipóteses são de condutas dolosas, mas nenhuma de menor potencial ofensivo.","há duas hipóteses de condutas culposas, uma delas de menor potencial ofensivo."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2014 • TEC 212439","source":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2014","subject":"Direito Penal - Moeda Falsa (art. 289 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/212439","year":2014,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-487080","sourceQuestionId":"487080","t":"pen-m10","moduleId":"pen-m10","q":"Janete recebeu de boa-fé como troco numa padaria uma nota falsa de cinquenta reais. Ao utilizá-la no comércio, foi cientificada de que se tratava de cédula falsa. Dirigiu-se, então, a outro estabelecimento e efetuou compras, pagando com a referida cédula, que, dessa forma, voltou a circular. Nesse caso, o crime de moeda falsa","o":["será imputado a Janete no tipo principal, punido com pena de reclusão e multa, porque introduziu na circulação cédula falsa sabendo da falsidade, sendo irrelevante a forma como a recebeu.","não será imputado a Janete, porque recebeu a cédula falsa de boa-fé, desconhecendo a falsidade.","será imputado a Janete, na modalidade privilegiada, punida com pena de detenção e de multa, porque, depois de conhecer a falsidade, restituiu a cédula à circulação.","não será imputado a Janete porque não adquiriu o papel-moeda por valor inferior ao que o mesmo, se verdadeiro, representaria.","não será imputado a Janete porque não foi ela a autora da fabricação ou alteração do papel-moeda colocado em circulação."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - Ana Min (MPE MA)/MPE MA/Processual/Direito/2013 • TEC 487080","source":"FCC - Ana Min (MPE MA)/MPE MA/Processual/Direito/2013","subject":"Direito Penal - Moeda Falsa (art. 289 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/487080","year":2013,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-684067","sourceQuestionId":"684067","t":"pen-m10","moduleId":"pen-m10","q":"Leo adquiriu de pessoa desconhecida um aparelho destinado à falsificação de moeda. Em seguida, fabricou várias cédulas falsas de cem reais e as colocou em circulação, adquirindo bens diversos. Nesse caso, Leo responderá","o":["pelos crimes de petrechos para falsificação de moeda, em continuidade delitiva.","unicamente pelo crime de petrechos para falsificação de moeda.","pelos crimes de petrechos para falsificação de moeda e moeda falsa, em concurso formal.","pelos crimes de petrechos para falsificação de moeda e moeda falsa, em concurso material.","unicamente pelo crime de moeda falsa."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - Ana Min (MPE PE)/MPE PE/Jurídica/2012 • TEC 684067","source":"FCC - Ana Min (MPE PE)/MPE PE/Jurídica/2012","subject":"Direito Penal - Moeda Falsa (art. 289 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/684067","year":2012,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3863329","sourceQuestionId":"3863329","t":"pen-m10","moduleId":"pen-m10","q":"O crime de falsificação de selos destinados a controle tributário, papel selado ou qualquer papel de emissão legal destinado à arrecadação de tributo","o":["admite a modalidade culposa, desde que a falsificação resulte de imperícia ou negligência na manipulação de papéis públicos, gerando resultado involuntário semelhante ao de falsidade típica.","não admite tentativa, pois a consumação ocorre somente quando o documento falsificado é efetivamente introduzido na circulação tributária, não havendo fase executória anterior penalmente relevante.","configura crime de mão própria, pois exige que o agente detenha atribuição funcional específica relacionada à confecção ou manipulação de selos fiscais, sob pena de atipicidade da conduta.","admite que a falsificação se realize tanto pela integral fabricação do objeto quanto pela modificação substancial de um selo ou papel autêntico, já que a lei equipara ambas as condutas à falsificação típica.","configura crime material, consumando-se apenas quando o documento falsificado produz efeito jurídico concreto ou quando o agente obtém vantagem tributária indevida mediante seu uso."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - FTE (SEFAZ MT)/SEFAZ MT/2026 • TEC 3863329","source":"FCC - FTE (SEFAZ MT)/SEFAZ MT/2026","subject":"Direito Penal - Falsificação de Papéis Públicos (art. 293 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3863329","year":2026,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3561326","sourceQuestionId":"3561326","t":"pen-m10","moduleId":"pen-m10","q":"Josué, aproveitando-se dos equipamentos emprestados por um amigo, falsificou inúmeros bilhetes de transporte público administrado por determinado Município, colocando-os em circulação. A polícia inicia intensa investigação e consegue apurar a autoria delitiva. Após obter a necessária ordem judicial, comparece na residência de Josué para cumprimento de mandado de busca domiciliar e de mandado de prisão preventiva contra ele. Josué acaba sendo preso pela polícia. Neste caso hipotético, na esteira do Código Penal, Josué cometeu, em tese, o crime de","o":["falsificação de selo ou sinal público.","fraude em certames de interesse público.","falsidade ideológica.","falsificação de papéis públicos.","falsificação de documento público."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/Geral/2025 • TEC 3561326","source":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/Geral/2025","subject":"Direito Penal - Falsificação de Papéis Públicos (art. 293 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3561326","year":2025,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3366525","sourceQuestionId":"3366525","t":"pen-m10","moduleId":"pen-m10","q":"Aquiles colou em seu veículo particular diversos adesivos com símbolos e emblemas identificadores da Policia Militar, ocasião em que passou a circular com o automóvel pelas ruas do Município de São Paulo. Ao ser abordado por policiais, admitiu a caracterização irregular de seu veículo. Considerando os elementos acima expostos, Aquiles","o":["não praticou qualquer crime, pois se trata de crime funcional.","praticou, em tese, o crime de reprodução ou adulteração de selo.","praticou, em tese, o crime de falsificação do selo ou sinal público.","praticou, em tese, o crime de falsidade ideológica.","não praticou qualquer crime, pois ausentes os elementos objetivos de qualquer tipo penal."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 3366525","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Penal - Falsificação do Selo ou Sinal Público (art. 296 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3366525","year":2025,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2638101","sourceQuestionId":"2638101","t":"pen-m10","moduleId":"pen-m10","q":"O crime de falsificação do selo ou sinal público","o":["abrange a falsificação de selo postal ou estampilha destinados à arrecadação de impostos ou taxas.","admite a modalidade culposa.","tem a mesma pena seja se cometido por funcionário público prevalecendo-se do cargo, seja se praticado por qualquer pessoa.","a pena é de detenção.","a pena é aplicada àquele que altera, falsifica ou faz uso indevido de marcas, logotipos, siglas ou quaisquer outros símbolos utilizados por órgãos da Administração pública."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AJ (TJ AP)/TJ AP/Judiciária e Administrativa/2014 • TEC 2638101","source":"FCC - AJ (TJ AP)/TJ AP/Judiciária e Administrativa/2014","subject":"Direito Penal - Falsificação do Selo ou Sinal Público (art. 296 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2638101","year":2014,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-23678","sourceQuestionId":"23678","t":"pen-m10","moduleId":"pen-m10","q":"Dentre os crimes contra a fé pública, NÃO constitui crime próprio","o":["a falsificação de selo ou sinal público.","o falso reconhecimento de firma ou letra.","a certidão ou atestado ideologicamente falso.","a falsidade de atestado médico.","a fraude de lei sobre estrangeiro."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - Proc (MP TCE-SP)/TCE SP/2011 • TEC 23678","source":"FCC - Proc (MP TCE-SP)/TCE SP/2011","subject":"Direito Penal - Falsificação do Selo ou Sinal Público (art. 296 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/23678","year":2011,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1014420","sourceQuestionId":"1014420","t":"pen-m10","moduleId":"pen-m10","q":"Configura o crime de falsificação de documento público o ato de","o":["reconhecer, como verdadeira, no exercício de função pública, firma ou letra que o não seja.","alterar documento público verdadeiro.","destruir, em benefício próprio ou de outrem, ou em prejuízo alheio, documento público verdadeiro, de que não podia dispor.","omitir, em documento público, declaração que dele devia constar, com o fim de alterar a verdade sobre fato juridicamente relevante.","dar o médico, no exercício da sua profissão, atestado falso."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - CL (CM Fortal)/CM Fortaleza/Advogado/2019 • TEC 1014420","source":"FCC - CL (CM Fortal)/CM Fortaleza/Advogado/2019","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1014420","year":2019,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-687893","sourceQuestionId":"687893","t":"pen-m10","moduleId":"pen-m10","q":"Acerca dos crimes contra a fé pública, o Código Penal dispõe:","o":["Comete o crime de falsificação de documento particular aquele que falsifica bilhete ou passe de empresa de transporte administrada pela União, por Estado ou por Município.","Equipara-se a documento público, para fins de falsificação, o cartão de crédito ou débito.","Para os efeitos penais, equiparam-se a documento público o emanado de entidade paraestatal, o título ao portador ou transmissível por endosso, as ações de sociedade comercial, os livros mercantis e o testamento particular.","No crime de falsidade material de atestado ou certidão é aplicável a pena de multa ainda que o crime não tenha sido praticado com o fim de lucro.","Pratica o crime de falsidade ideológica aquele que falsifica, no todo ou em parte, documento particular verdadeiro."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - Con Tec Leg (CL DF)/CL DF/Inspetor de Polícia Legislativa/2018 • TEC 687893","source":"FCC - Con Tec Leg (CL DF)/CL DF/Inspetor de Polícia Legislativa/2018","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/687893","year":2018,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-460487","sourceQuestionId":"460487","t":"pen-m10","moduleId":"pen-m10","q":"À luz do Código Penal, sobre a falsidade documental nos crimes contra a fé pública,","o":["a falsificação de um documento emanado de sociedade de economia mista federal caracteriza o crime de falsificação de documento público.","equipara-se a documento público para caracterização do crime de falsificação de documento público o cartão de crédito ou débito.","se o autor do crime de falsificação de selo ou sinal público é funcionário público e comete o crime prevalecendo-se do cargo, a pena é aumentada de um terço.","aquele que faz inserir na Carteira de Trabalho e Previdência Social do empregado declaração falsa ou diversa da que deveria ter constado estará sujeito às penas cominadas ao crime de falsidade ideológica.","o médico que dá, no exercício de sua função, atestado falso com o fim lucrativo estará sujeito à pena privativa de liberdade cominada ao delito de falsidade de atestado médico aumentada de metade."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AJ TRE SP/TRE SP/Judiciária/2017 • TEC 460487","source":"FCC - AJ TRE SP/TRE SP/Judiciária/2017","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/460487","year":2017,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-261723","sourceQuestionId":"261723","t":"pen-m10","moduleId":"pen-m10","q":"Murilo, funcionário público, escrevente judiciário de um determinado Tribunal de Justiça brasileiro, no exercício regular de suas atividades junto ao Cartório de uma vara criminal, elabora um alvará de soltura falso em nome de Moisés, réu preso por ordem da Justiça por crime de homicídio, inclusive com falsificação da assinatura do Magistrado competente, encaminhando-o ao Centro de Detenção Provisória onde o réu Moisés encontra-se recolhido. Moisés não é colocado em liberdade, pois havia outro mandado de prisão expedido em seu desfavor em decorrência de outro delito por ele cometido. Neste caso, Murilo cometeu crime de","o":["falsificação de documento público consumado e terá sua pena aumentada da sexta parte por ser funcionário público e ter cometido o crime prevalecendo-se do cargo.","falsificação de documento público tentado, uma vez que Moisés não foi colocado em liberdade, não produzindo o resultado final pretendido pelo agente, sem qualquer majoração da pena privativa de liberdade pelo fato de ser funcionário público.","falsidade ideológica consumada, com a pena aumentada da terça parte pelo fato de ser funcionário público e ter cometido o crime prevalecendo-se do cargo.","falsidade ideológica tentada, sem qualquer majoração da pena privativa de liberdade por ser funcionário público.","falsificação de documento público tentado, uma vez que Moisés não foi colocado em liberdade, não produzindo o resultado final pretendido pelo agente, com a pena majorada da sexta parte em razão de ser funcionário público e ter cometido o crime prevalecendo- se do cargo."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AJ TRE RR/TRE RR/Judiciária/2015 • TEC 261723","source":"FCC - AJ TRE RR/TRE RR/Judiciária/2015","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/261723","year":2015,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-300675","sourceQuestionId":"300675","t":"pen-m10","moduleId":"pen-m10","q":"Segundo disposição expressa da lei penal, quem insere na folha de pagamento, ou em documento de informações que seja destinado a fazer prova perante a previdência social, pessoa que não possua a qualidade de segurado obrigatório incorre nas penas cominadas ao delito de","o":["sonegação de contribuição previdenciária.","falsificação de documento público.","uso de documento falso.","falsificação de documento particular.","falsidade ideológica."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - JT TRT15/TRT 15/2015 • TEC 300675","source":"FCC - JT TRT15/TRT 15/2015","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/300675","year":2015,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-254671","sourceQuestionId":"254671","t":"pen-m10","moduleId":"pen-m10","q":"Segundo o Código Penal, a conduta do empregador de lançar anotação falsa na carteira de trabalho dos empregados pode ser tipificada como","o":["falsificação de documento público.","falsificação de documento particular.","uso de documento falso.","estelionato.","fraude trabalhista."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - JT TRT1/TRT 1/2014 • TEC 254671","source":"FCC - JT TRT1/TRT 1/2014","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/254671","year":2014,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2638071","sourceQuestionId":"2638071","t":"pen-m10","moduleId":"pen-m10","q":"Com relação ao crime de falsificação de documento público, é INCORRETO afirmar:","o":["Equipara-se a documento público o emanado de entidade paraestatal, o título ao portador ou transmissível por endosso, as ações de sociedade comercial, os livros mercantis e o testamento particular.","Se o sujeito ativo for funcionário público e comete o crime prevalecendo-se do cargo, aumenta-se a pena de sexta parte.","A pena é de reclusão, de dois a seis anos, e multa.","Incorre na mesma pena desse crime aquele que insere ou faz inserir na Carteira de Trabalho e Previdência Social do empregado ou em documento que deva produzir efeito perante a Previdência Social, declaração falsa ou diversa da que deveria ter sido escrita.","Incorre na mesma pena desse crime aquele que insere ou faz inserir na folha de pagamento, ou em documento de informações que seja destinado a fazer prova perante a Previdência Social, pessoa que possua a qualidade de segurado obrigatório."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AJ (TJ AP)/TJ AP/Judiciária/Execução de Mandados/2014 • TEC 2638071","source":"FCC - AJ (TJ AP)/TJ AP/Judiciária/Execução de Mandados/2014","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2638071","year":2014,"caderno":4,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2638166","sourceQuestionId":"2638166","t":"pen-m10","moduleId":"pen-m10","q":"A propósito da falsidade documental, é correto afirmar:","o":["O documento particular não pode ser objeto do crime de falsidade ideológica.","O testamento particular não pode ser objeto do cri me de falsificação de documento público.","O crime de falsificação de documento particular ocorre apenas com a falsificação integral do documento.","O cartão de débito ou crédito equipara-se a documento particular.","Os livros mercantis não podem ser objeto do crime de falsificação de documento público."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - TJ (TJ AP)/TJ AP/Judiciária e Administrativa/2014 • TEC 2638166","source":"FCC - TJ (TJ AP)/TJ AP/Judiciária e Administrativa/2014","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2638166","year":2014,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-97238","sourceQuestionId":"97238","t":"pen-m10","moduleId":"pen-m10","q":"Em relação ao delito de falsificação de documento público, é correto afirmar que","o":["também o configura a falsificação do conteúdo do documento, embora verdadeira a forma.","os títulos transmissíveis por endosso podem ser objeto material da infração.","a pena deve ser aumentada da sexta parte se o agente é funcionário público, mesmo que não se prevaleça do cargo.","admite a forma culposa.","não é absorvido pelo estelionato, ainda que nele se exaure, sem mais potencialidade lesiva, segundo entendimento sumulado do Superior Tribunal de Justiça."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AFRE (SEFAZ SP)/SEFAZ SP/Tecnologia da Informação/2013 • TEC 97238","source":"FCC - AFRE (SEFAZ SP)/SEFAZ SP/Tecnologia da Informação/2013","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/97238","year":2013,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-184076","sourceQuestionId":"184076","t":"pen-m10","moduleId":"pen-m10","q":"Segundo a legislação penal, aquele que, na folha de pagamento, insere ou faz inserir pessoa que não possua a qualidade de segurado obrigatório, comete o crime de","o":["falsificação de documento particular.","falsificação de documento público.","atentado contra a liberdade de contrato de trabalho.","falsidade ideológica.","sonegação de contribuição previden ciária."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - JT TRT6/TRT 6/2013 • TEC 184076","source":"FCC - JT TRT6/TRT 6/2013","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/184076","year":2013,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1408567","sourceQuestionId":"1408567","t":"pen-m10","moduleId":"pen-m10","q":"A respeito do crime de falsificação de documento público, é correto afirmar:","o":["Os documentos emanados de entidades paraestatais não se equiparam a documento público.","Caracteriza-se a forma culposa do delito, quando o agente alterar documento por equívoco e sem a intenção de prejudicar quem quer que seja.","É desnecessária para a caracterização desse delito que a falsificação apresente a possibilidade de prejuízo.","O testamento particular equipara-se a documento público para os efeitos penais.","Só o funcionário público pode ser sujeito ativo desse delito."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - Ag Tec (MPE AM)/MPE AM/Jurídico/2013 • TEC 1408567","source":"FCC - Ag Tec (MPE AM)/MPE AM/Jurídico/2013","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1408567","year":2013,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-85075","sourceQuestionId":"85075","t":"pen-m10","moduleId":"pen-m10","q":"Para efeitos penais, NÃO se equipara a documento público","o":["o cheque.","o atestado médico particular.","a duplicata.","as ações de sociedade comercial.","a letra de câmbio."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - JT TRT1/TRT 1/2012 • TEC 85075","source":"FCC - JT TRT1/TRT 1/2012","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/85075","year":2012,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-116718","sourceQuestionId":"116718","t":"pen-m10","moduleId":"pen-m10","q":"Incorre nas penas cominadas ao delito de falsificação de documento público quem","o":["deixa de lançar mensalmente nos títulos próprios da contabilidade da empresa as quantias descontadas dos segurados ou as devidas pelo empregador ou pelo tomador de serviços.","insere, em documento contábil ou em qualquer outro documento relacionado com as obrigações da empresa perante a previdência social, declaração falsa ou diversa da que deveria ter constado.","omite, total ou parcialmente, receitas ou lucros auferidos, remunerações pagas ou creditadas e demais fatos geradores de contribuições sociais previdenciárias.","omite de folha de pagamento da empresa ou de documentos de informações previstos pela legislação previdenciária segurados empregado, empresário, trabalhador avulso ou trabalhador autônomo ou a este equiparado que lhe prestem serviços.","insere, em documento particular, declaração falsa ou diversa da que devia ser escrita, com o fim de prejudicar direito, criar obrigação ou alterar verdade sobre fato juridicamente relevante."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - JT TRT4/TRT 4/2012 • TEC 116718","source":"FCC - JT TRT4/TRT 4/2012","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/116718","year":2012,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-187353","sourceQuestionId":"187353","t":"pen-m10","moduleId":"pen-m10","q":"NÃO incorre nas penas cominadas ao delito de falsificação de documento público quem","o":["omite, em documento público, declaração que dele devia constar, ou nele insere ou faz inserir declaração falsa ou diversa da que devia ser escrita, com o fim de prejudicar direito, criar obrigação ou alterar a verdade sobre fato juridicamente relevante.","insere, em documento contábil ou em qualquer outro documento relacionado com as obrigações da empresa perante a previdência social, declaração falsa ou diversa da que deveria ter constado.","insere, na folha de pagamento ou documento de informações que seja destinado a fazer prova perante a previdência social, pessoa que não possua a qualidade de segurado obrigatório.","omite, em documento relacionado com as obrigações da empresa perante a previdência social, o nome do segurado e seus dados pessoais, a remuneração, a vigência do contrato de trabalho ou de prestação de serviços.","faz inserir, na Carteira de Trabalho e Previdência Social do empregado ou em documento que deva produzir efeito perante a previdência social, declaração falsa ou diversa da que deveria ter sido escrita."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - JT TRT11/TRT 11/2012 • TEC 187353","source":"FCC - JT TRT11/TRT 11/2012","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/187353","year":2012,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-443619","sourceQuestionId":"443619","t":"pen-m10","moduleId":"pen-m10","q":"Para os efeitos penais, NÃO se equipara a documento público,","o":["o documento emanado de entidade paraestatal.","o recibo de quitação de honorários emitido por advogado.","o título ao portador transmissível por endosso.","os livros mercantis.","o testamento particular."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - Ana (MPE RN)/MPE RN/Inteligência/2012 • TEC 443619","source":"FCC - Ana (MPE RN)/MPE RN/Inteligência/2012","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/443619","year":2012,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-23677","sourceQuestionId":"23677","t":"pen-m10","moduleId":"pen-m10","q":"No crime de falsificação de documento público,","o":["ser o agente funcionário público é causa de aumento da pena, ainda que não se tenha prevalecido do cargo.","a forma do documento é verdadeira, mas seu conteúdo é falso.","o objeto material pode ser testamento particular.","a falsificação deve ser integral, não se punindo a meramente parcial.","não basta para a tipificação da infração a alteração de documento público verdadeiro."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - Proc (MP TCE-SP)/TCE SP/2011 • TEC 23677","source":"FCC - Proc (MP TCE-SP)/TCE SP/2011","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/23677","year":2011,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-65240","sourceQuestionId":"65240","t":"pen-m10","moduleId":"pen-m10","q":"Aquele que falsifica a assinatura de avalista numa nota promissória, da qual é credor, responderá pelo crime de","o":["falsa identidade.","falsidade ideológica.","falsificação de documento particular.","falsificação de documento público.","uso de documento falso."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AJ (TRF 1ª Região)/TRF 1/Judiciária/Oficial de Justiça Avaliador Federal/2011 • TEC 65240","source":"FCC - AJ (TRF 1ª Região)/TRF 1/Judiciária/Oficial de Justiça Avaliador Federal/2011","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/65240","year":2011,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-84838","sourceQuestionId":"84838","t":"pen-m10","moduleId":"pen-m10","q":"Aquele que, em documento que deva produzir efeito perante a previdência social, insere declaração falsa ou diversa da que deveria ter sido escrita, comete o crime de","o":["falsificação de documento particular.","frustração de direito assegurado por lei trabalhista.","falsificação de documento público.","uso de documento falso.","supressão de documento."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - JT TRT1/TRT 1/2011 • TEC 84838","source":"FCC - JT TRT1/TRT 1/2011","subject":"Direito Penal - Falsificação de Documento Público (art. 297 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/84838","year":2011,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-789043","sourceQuestionId":"789043","t":"pen-m10","moduleId":"pen-m10","q":"Nos crimes contra a Fé Pública,","o":["se o médico fornecer atestado falso, no exercício de sua profissão, é crime apenado com reclusão; se o crime tiver intuito de lucro, considerar-se-á estelionato.","o recebimento de moeda falsa ou alterada, de boa ou má-fé, restituindo-a em circulação, conhecendo ou devendo conhecer a falsidade, é crime punido com reclusão e multa.","a falsificação, no todo ou parcialmente, de documento público, ou a alteração de documento público ou particular verdadeiro, se o agente for funcionário público e cometer o crime prevalecendo-se do cargo, é causa de aumento de pena de um a dois terços.","não configura crime, nem mesmo em tese, não autorizando nem sequer investigação criminal, a utilização de papel-moeda grosseiramente falsificado.","para fins de tipificação do crime de falsificação de documento particular, equipara-se a documento particular o cartão de crédito ou débito."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019 • TEC 789043","source":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019","subject":"Direito Penal - Falsificação de Documento Particular (art. 298 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/789043","year":2019,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-264795","sourceQuestionId":"264795","t":"pen-m10","moduleId":"pen-m10","q":"Falsificar cartão de crédito ou débito é","o":["crime de falsificação de documento particular.","crime de falsa identidade.","crime de falsidade ideológica.","crime de falsificação de documento público, por equiparação.","conduta atípica."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - JE TJGO/TJ GO/2015 • TEC 264795","source":"FCC - JE TJGO/TJ GO/2015","subject":"Direito Penal - Falsificação de Documento Particular (art. 298 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/264795","year":2015,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-204756","sourceQuestionId":"204756","t":"pen-m10","moduleId":"pen-m10","q":"Falsificar cartão de crédito é","o":["conduta atípica.","falsificação de documento público.","falsidade ideológica.","falsa identidade.","falsificação de documento particular."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - JT TRT18/TRT 18/2014 • TEC 204756","source":"FCC - JT TRT18/TRT 18/2014","subject":"Direito Penal - Falsificação de Documento Particular (art. 298 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/204756","year":2014,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-132685","sourceQuestionId":"132685","t":"pen-m10","moduleId":"pen-m10","q":"Em relação aos crimes contra a fé pública previstos no Código Penal brasileiro é correto afirmar,","o":["Excepcionalmente admitem a modalidade culposa quando se tratar de falsificação de documento particular.","Exigem como elemento a imitação ou alteração da verdade; a possibilidade de dano e o dolo.","A alteração inapta a induzir número indeterminado de pessoas leva à consideração da forma tentada em qualquer caso.","No crime de moeda falsa, mesmo ausente a capacidade ilusória da contrafação, tem-se caracterizada sua consumação.","Tratando-se de crimes formais não admitem forma tentada."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AJ TRF5/TRF 5/Judiciária/\"Sem Especialidade\"/2013 • TEC 132685","source":"FCC - AJ TRF5/TRF 5/Judiciária/\"Sem Especialidade\"/2013","subject":"Direito Penal - Falsificação de Documento Particular (art. 298 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/132685","year":2013,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-59067","sourceQuestionId":"59067","t":"pen-m10","moduleId":"pen-m10","q":"No que concerne aos crimes contra a fé pública, é INCORRETO afirmar que","o":["o testamento particular é considerado documento público para os efeitos penais.","não há crime se a falsidade ideológica versar sobre fato juridicamente irrelevante.","não há falsidade ideológica se o conteúdo da declaração retrata a opinião do agente e não um fato.","para a caracterização do crime de falsidade ideológica basta a potencialidade de um evento danoso.","o crime de falsificação de documento particular pode ser praticado na forma dolosa ou culposa."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AFTM SP/Pref SP/Tecnologia da Informação/2012 • TEC 59067","source":"FCC - AFTM SP/Pref SP/Tecnologia da Informação/2012","subject":"Direito Penal - Falsificação de Documento Particular (art. 298 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/59067","year":2012,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2572532","sourceQuestionId":"2572532","t":"pen-m10","moduleId":"pen-m10","q":"Paulo recebeu um cheque de R$ 300,00 em pagamento da venda de mercadoria. Depositado, o cheque foi devolvido por insuficiência de fundos. Novamente depositado, tornou a ser devolvido por insuficiência de fundos. Após seis meses, tendo ocorrido a prescrição, Paulo endossou o cheque e o transferiu a José, que alterou o valor para R$ 3.000,00 e ingressou em juízo com ação monitória contra o emitente. Nesse caso, José","o":["não responderá por nenhum delito porque o cheque estava prescrito.","responderá por falsificação de documento particular.","responderá por falsificação de documento público.","responderá por uso de documento público falso.","responderá por uso de papel público alterado."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AS-II (INFRAERO)/INFRAERO/Advogado/2011 • TEC 2572532","source":"FCC - AS-II (INFRAERO)/INFRAERO/Advogado/2011","subject":"Direito Penal - Falsificação de Documento Particular (art. 298 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2572532","year":2011,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1818206","sourceQuestionId":"1818206","t":"pen-m10","moduleId":"pen-m10","q":"Configura o crime de falsidade ideológica:","o":["falsificar, no todo ou em parte, documento público, ou alterar documento público verdadeiro.","omitir, em documento público ou particular, declaração que dele devia constar, ou nele inserir ou fazer inserir declaração falsa ou diversa da que devia ser escrita, com o fim de prejudicar direito, criar obrigação ou alterar a verdade sobre fato juridicamente relevante.","utilizar ou divulgar, indevidamente, com o fim de beneficiar a si ou a outrem, ou de comprometer a credibilidade do certame, conteúdo sigiloso de concurso público.","falsificar, no todo ou em parte, atestado ou certidão, ou alterar o teor de certidão ou de atestado verdadeiro, para prova de fato ou circunstância que habilite alguém a obter cargo público, isenção de ônus ou de serviço de caráter público, ou qualquer outra vantagem.","atribuir-se, ou atribuir a terceiro, falsa identidade para obter vantagem, em proveito próprio ou alheio, ou para causar dano a outrem."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - TJ Aux (TJ SC)/TJ SC/2021 • TEC 1818206","source":"FCC - TJ Aux (TJ SC)/TJ SC/2021","subject":"Direito Penal - Falsidade Ideológica (art. 299 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1818206","year":2021,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1037277","sourceQuestionId":"1037277","t":"pen-m10","moduleId":"pen-m10","q":"Quanto aos crimes contra a fé pública,","o":["compete à Justiça Estadual comum processar e julgar civil denunciado pelos crimes de falsificação e de uso de documento público falso quando se tratar de Carteira de Habilitação de Amador, ainda que expedida pela Marinha do Brasil.","há sempre concurso entre os crimes de falsificação de documento público e estelionato, segundo entendimento do sumulado do Superior Tribunal de Justiça.","configura crime de falsificação de documento particular o ato de falsificar, no todo ou em parte, testamento particular, duplicata e cartão bancário de crédito ou débito.","atípica a conduta de, em situação de autodefesa, atribuir-se falsa identidade perante autoridade policial.","inadmissível proposta de suspensão condicional do processo no crime de falsidade ideológica de assentamento de registro civil."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - JE TJAL/TJ AL/2019 • TEC 1037277","source":"FCC - JE TJAL/TJ AL/2019","subject":"Direito Penal - Falsidade Ideológica (art. 299 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1037277","year":2019,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-682662","sourceQuestionId":"682662","t":"pen-m10","moduleId":"pen-m10","q":"Pratica o crime de falsidade ideológica aquele que","o":["faz uso de carteira nacional de habilitação falsa em abordagem policial para evitar multa administrativa.","altera ou falsifica documento particular verdadeiro e o utiliza no Brasil ou no exterior.","atesta falsamente, em razão de função pública, fato que habilite alguém a obter cargo público.","atribui-se falsa identidade para obter vantagem, em proveito próprio ou alheio, ou para causar dano a outrem.","omite, em documento particular, declaração que dele devia constar com o fim de criar uma obrigação."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - Proc Leg (CL DF)/CL DF/2018 • TEC 682662","source":"FCC - Proc Leg (CL DF)/CL DF/2018","subject":"Direito Penal - Falsidade Ideológica (art. 299 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/682662","year":2018,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-228254","sourceQuestionId":"228254","t":"pen-m10","moduleId":"pen-m10","q":"A falsa declaração de parentesco para que o interessado na aquisição de imóvel pelo Sistema Financeiro da Habitação consiga atingir a renda exigida caracteriza o crime de","o":["falsificação de documento público.","falsidade ideológica.","falsificação de documento particular.","falsidade material de atestado.","atestado ideologicamente falso."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - ACE (TCE-GO)/TCE GO/Jurídica/2014 • TEC 228254","source":"FCC - ACE (TCE-GO)/TCE GO/Jurídica/2014","subject":"Direito Penal - Falsidade Ideológica (art. 299 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/228254","year":2014,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-385791","sourceQuestionId":"385791","t":"pen-m10","moduleId":"pen-m10","q":"No que concerne aos crimes de falsidade documental, é correto afirmar que","o":["a falsificação de testamento particular tipifica o delito de falsificação de documento público e a de duplicata o crime de falsificação de documento particular.","na falsidade ideológica é fraudada a própria forma do documento, alterada no todo ou em parte.","o estelionato se exaure no falso e é por este absorvido quando não revele mais potencialidade lesiva, segundo entendimento sumulado do Superior Tribunal de Justiça.","há concurso material de infrações se o agente, além de falsificar, também usar o documento fraudado, consoante pacífico entendimento dos Tribunais Superiores.","configura causa de aumento da pena nos delitos de falsificação de documento público e falsidade ideológica a circunstância de o agente ser funcionário público e cometer o crime prevalecendo-se do cargo."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - JT TRT20/TRT 20/2012 • TEC 385791","source":"FCC - JT TRT20/TRT 20/2012","subject":"Direito Penal - Falsidade Ideológica (art. 299 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/385791","year":2012,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-443576","sourceQuestionId":"443576","t":"pen-m10","moduleId":"pen-m10","q":"Paulo viajou e deixou com Pedro um papel assinado em branco para este preencher, elaborando o recibo de aluguel de um imóvel de sua propriedade. Pedro, no entanto, preencheu o documento, elaborando recibo de quitação geral de todas as dívidas que tinha com Paulo. Essa conduta caracterizou","o":["crime de falsificação de documento público.","mero ilícito civil penalmente irrelevante.","crime de falsificação de documento particular.","crime de falsidade ideológica.","crime de falsidade material de atestado ou certidão."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - Ana (MPE RN)/MPE RN/Diligências/2012 • TEC 443576","source":"FCC - Ana (MPE RN)/MPE RN/Diligências/2012","subject":"Direito Penal - Falsidade Ideológica (art. 299 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/443576","year":2012,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-62734","sourceQuestionId":"62734","t":"pen-m10","moduleId":"pen-m10","q":"A diferença entre falsidade material e ideológica de documento é que na falsidade material","o":["frauda-se a forma do documento e na ideológica o conteúdo é falso.","frauda-se o conteúdo e na ideológica a forma do documento.","a conduta é omissiva, e no falso ideológico ela é comissiva.","exige-se o dolo e na ideológica aceita-se a culpa.","há previsão de aumento especial de pena e na ideológica não."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - ACE (TCE PR)/TCE PR/Jurídica/2011 • TEC 62734","source":"FCC - ACE (TCE PR)/TCE PR/Jurídica/2011","subject":"Direito Penal - Falsidade Ideológica (art. 299 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/62734","year":2011,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-315365","sourceQuestionId":"315365","t":"pen-m10","moduleId":"pen-m10","q":"Sobre os crimes de falsidade documental é INCORRETO afirmar:","o":["Está sujeito às penas do crime de falsificação de documento público quem insere na Carteira de Trabalho e Previdência Social do empregado declaração diversa da que deveria ter sido escrita.","Equipara-se a documento particular para caracterização do crime de falsificação de documento particular o cartão de crédito ou débito.","No caso de falsidade ideológica se o agente é funcionário público e falsifica assentamento de registro civil aumenta-se a pena cominada ao delito de sexta parte.","O médico que dá, no exercício de sua profissão, atestado falso está sujeito ao crime de falsidade de atestado médico com pena de detenção de um mês a um ano majorada de 1/3 se o crime for cometido com intuito de lucro.","O testamento particular e as ações de sociedade comercial equiparam-se a documento público para caracterização do crime de falsificação de documento público."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AJ TRE AP/TRE AP/Judiciária/2015 • TEC 315365","source":"FCC - AJ TRE AP/TRE AP/Judiciária/2015","subject":"Direito Penal - Falsidade de Atestado Médico (art. 302 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/315365","year":2015,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3883970","sourceQuestionId":"3883970","t":"pen-m10","moduleId":"pen-m10","q":"Eliane é empregada contratada de uma empresa privada que realizava eventos na cidade de Cuiabá. Uma semana antes do carnaval, Eliane ficou doente e foi a um hospital da rede SUS (Sistema Único de Saúde), ocasião em que o médico lhe deu um atestado determinando seu afastamento do trabalho por 4 dias. Ocorre que Eliane decidiu aproveitar essa chance para emendar o feriado do carnaval, alterando, ela própria, o número de dias de afastamento constante no atestado para 8 dias. Eliane então mandou seu atestado para o Recursos Humanos da empresa para abonar suas faltas. Todavia, o funcionário do RH descobriu a falsidade e encaminhou o caso à polícia. De acordo com a jurisprudência majoritária do Superior Tribunal de Justiça, a conduta de Eliane configura","o":["uso de documento falso, com a pena prevista para falsificação de documento público.","uso de documento falso e falsidade ideológica, em concurso formal.","uso de documento falso, com a pena prevista para a falsificação de documento particular.","falsidade material de atestado ou certidão.","conduta atípica."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - DP MT/DPE MT/2026 • TEC 3883970","source":"FCC - DP MT/DPE MT/2026","subject":"Direito Penal - Uso de Documento Falso (art. 304 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3883970","year":2026,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-662235","sourceQuestionId":"662235","t":"pen-m10","moduleId":"pen-m10","q":"Comete o crime de","o":["falsa identidade aquele faz uso de Carteira Nacional de Habilitação (CNH) falsa para conduzir veículo automotor.","falso testemunho aquele que imputa a outrem falsamente fato definido como crime.","uso de documento falso aquele que faz uso de documento particular falso.","falsidade de atestado médico aquele produz atestado falso se passando pela condição de médico.","falsificação de documento público aquele que insere em documento público declaração falsa com o fim de prejudicar direito de terceiro."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - DP AM/DPE AM/2018 • TEC 662235","source":"FCC - DP AM/DPE AM/2018","subject":"Direito Penal - Uso de Documento Falso (art. 304 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/662235","year":2018,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-322205","sourceQuestionId":"322205","t":"pen-m10","moduleId":"pen-m10","q":"Antonio Célio, barista, faltou injustificadamente ao trabalho, nada comunicando ao empregador. Por ser reincidente, já tendo sido punido por ausências anteriores, e temendo ser dispensado por justa causa, no dia seguinte − que era destinado a sua folga − se aproveita do comparecimento à clínica médica “Saúde Real Cop” onde marcara consulta e, verificando a momentânea ausência de fiscalização, pega para si carimbo do médico responsável pela clínica. Na saída, para eliminar registro de sua presença, destrói a folha usada pela administração da clínica para controle dos pacientes que lá comparecem, documento adotado para instruir os requerimentos de pagamento por serviços prestados pela clínica a várias operadoras de plano de saúde. Em seguida, Antonio Célio vai para casa, onde elabora atestado médico que justificaria sua ausência ao trabalho, assina-o com o nome do médico constante do carimbo, além de efetuar, ele próprio, reconhecimento da firma que inserira no atestado. Por fim, dois dias após a ausência ao trabalho, Antônio Célio entrega o documento nos moldes acima ao seu empregador, solicitando que não houvesse o desconto de sua falta. Além de outros, caso estejam presentes, configura-se a existência dos seguintes tipos penais, praticados por Antônio Célio:","o":["supressão de documento, falsificação de documento particular e uso de documento falso.","falsificação de documento particular, falso reconhecimento de firma e furto.","falso reconhecimento de firma, falsidade de atestado médico e uso de documento falso.","falsidade de atestado médico, furto e supressão de documento.","furto, falsidade de reconhecimento de firma e falsidade de atestado médico."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - JT TRT1/TRT 1/2015 • TEC 322205","source":"FCC - JT TRT1/TRT 1/2015","subject":"Direito Penal - Uso de Documento Falso (art. 304 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/322205","year":2015,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-120540","sourceQuestionId":"120540","t":"pen-m10","moduleId":"pen-m10","q":"Clemente falsificou um alvará judicial para levantamento de depósito judicial em nome de Clementina. Clementina foi até a agência bancária e o apresentou ao caixa, que acabou descobrindo a falsificação. Nesse caso, Clemente","o":["e Clementina responderão pelo crime de falsificação de papéis públicos.","responderá pelo crime de falsificação de documento público e Clementina por uso de documento falso.","e Clementina responderão pelo crime de falsificação de documento público.","responderá pelo crime de falsificação de papéis públicos e Clementina por uso de papel público falsificado.","responderá pelo crime de falsificação de documento particular e Clementina por uso de documento falso."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AJ TRF2/TRF 2/Judiciária/\"Sem Especialidade\"/2012 • TEC 120540","source":"FCC - AJ TRF2/TRF 2/Judiciária/\"Sem Especialidade\"/2012","subject":"Direito Penal - Uso de Documento Falso (art. 304 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/120540","year":2012,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-23676","sourceQuestionId":"23676","t":"pen-m10","moduleId":"pen-m10","q":"No crime de uso de documento falso,","o":["a infração não se tipifica no caso de a falsidade do documento utilizado ser meramente ideológica.","a pena cominada é sempre a mesma, independentemente da natureza do documento.","há concurso com o delito de falso, se o agente que usa o documento é o próprio responsável pela falsificação, segundo amplo entendimento jurisprudencial.","o objeto material pode ser simples fotocópia falsificada, ainda que não autenticada.","a consumação se dá com o efetivo uso do documento, não se exigindo resultado naturalístico, já que se trata de delito formal."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - Proc (MP TCE-SP)/TCE SP/2011 • TEC 23676","source":"FCC - Proc (MP TCE-SP)/TCE SP/2011","subject":"Direito Penal - Uso de Documento Falso (art. 304 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/23676","year":2011,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-378025","sourceQuestionId":"378025","t":"pen-m10","moduleId":"pen-m10","q":"O crime de uso de documento falso","o":["só se caracteriza se a falsidade do documento for material.","é punível a título de culpa.","caracteriza-se independentemente do agente ter ciência da falsidade.","pode ser cometido com dolo eventual.","não pode ser cometido pelo autor da falsificação."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AJ (TRE PE)/TRE PE/Judiciária/2011 • TEC 378025","source":"FCC - AJ (TRE PE)/TRE PE/Judiciária/2011","subject":"Direito Penal - Uso de Documento Falso (art. 304 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/378025","year":2011,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3091249","sourceQuestionId":"3091249","t":"pen-m10","moduleId":"pen-m10","q":"Durante uma abordagem policial por suspeita de prática de crime, José Bonilácio da Silva apresentou-se perante a autoridade policial e subscreveu o Termo de Auto de Prisão em Flagrante Delito e Termo de Qualificação, Vida Pregressa e Interrogatório com o nome de Pedro de Alcântara. Horas depois, quando Benjamin da Silva, filho de José Bonilácio, compareceu à Delegacia de Polícia para prestar esclarecimentos sobre a prisão de seu genitor, os agentes públicos verificaram sua certidão de nascimento, ocasião em que constataram o verdadeiro nome do suspeito. Considerando tão somente as informações apresentadas na questão, José Bonifácio teria praticado, em tese, o crime de:","o":["falsidade ideológica.","falsidade de identidade.","falsificação de documento público.","uso de documento falso.","supressão de documento."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - TJ (TJ AL)/TJ AL/Judiciária/2024 • TEC 3091249","source":"FCC - TJ (TJ AL)/TJ AL/Judiciária/2024","subject":"Direito Penal - Falsa Identidade (arts. 307 a 308 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3091249","year":2024,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1005168","sourceQuestionId":"1005168","t":"pen-m10","moduleId":"pen-m10","q":"De acordo com o ordenamento jurídico e o posicionamento dos tribunais superiores acerca dos crimes contra a fé pública,","o":["não comete o delito de falsa identidade (art. 307) do Código Penal aquele que, conduzido perante a autoridade policial, atribui a si falsa identidade com o intuito de ocultar seus antecedentes, tendo em vista o princípio da autodefesa.","assim como nos demais crimes não patrimoniais em geral, os delitos contra a fé pública são incompatíveis com o instituto do arrependimento posterior, dada a impossibilidade material de haver reparação do dano causado ou a restituição da coisa subtraída.","a conduta do agente que altera, em parte, testamento particular, é tipificada como falsificação de documento particular.","tanto o charlatanismo (art. 283), quanto o curandeirismo (art. 284), são classificados no Código Penal como crimes contra a fé pública.","fabricar, adquirir, fornecer, possuir ou guardar objeto especialmente destinado à falsificação de qualquer papel público constitui contravenção penal."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - Prom Jus (MPE MT)/MPE MT/2019 • TEC 1005168","source":"FCC - Prom Jus (MPE MT)/MPE MT/2019","subject":"Direito Penal - Falsa Identidade (arts. 307 a 308 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1005168","year":2019,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-396937","sourceQuestionId":"396937","t":"pen-m10","moduleId":"pen-m10","q":"O crime de falsa identidade","o":["só se consuma com a obtenção de vantagem ilícita.","não admite tentativa.","pode ser cometido na forma culposa.","pode ser cometido por qualquer pessoa.","é punido com pena de reclusão de 1 a 4 anos."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - AFRM (Pref Teresina)/Pref Teresina/2016 • TEC 396937","source":"FCC - AFRM (Pref Teresina)/Pref Teresina/2016","subject":"Direito Penal - Falsa Identidade (arts. 307 a 308 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/396937","year":2016,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-283674","sourceQuestionId":"283674","t":"pen-m10","moduleId":"pen-m10","q":"Quanto ao crime de uso de documento de identidade alheia como próprio, é INCORRETO afirmar que","o":["a carteira profissional pode ser objeto material do delito.","não se exige que o uso tenha por finalidade a obtenção de vantagem.","a consumação ocorre com o uso de documento de identidade alheia.","não é necessário que o uso tenha por objetivo causar dano a outrem.","na forma culposa é necessário que agente tenha consciência de que o uso é ilícito."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - Proc (TCM-RJ)/TCM RJ/2015 • TEC 283674","source":"FCC - Proc (TCM-RJ)/TCM RJ/2015","subject":"Direito Penal - Falsa Identidade (arts. 307 a 308 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/283674","year":2015,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-69397","sourceQuestionId":"69397","t":"pen-m10","moduleId":"pen-m10","q":"Quem","o":["corrige erros materiais em um contrato comete crime de alteração de documento particular verdadeiro.","desvia e faz circular moeda cuja circulação não estava autorizada só responde por crime contra a fé pública se a autorização para circulação não vier a ser dada.","possui objeto especialmente destinado à falsificação de moeda só responde por crime contra a fé pública se vier a utilizá-lo efetivamente para a falsificação de moeda.","comparece a juízo sob nome falso, a fim de manter-se isento da mácula nos registros públicos, comete crime de falsa identidade.","restitui à circulação, tendo recebido de boa fé, como verdadeira, moeda falsa ou alterada, depois de conhecer a falsidade, não comete nenhum delito."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - ACE TCE AP/TCE AP/Apoio Administrativo/Jurídica/2012 • TEC 69397","source":"FCC - ACE TCE AP/TCE AP/Apoio Administrativo/Jurídica/2012","subject":"Direito Penal - Falsa Identidade (arts. 307 a 308 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/69397","year":2012,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-424480","sourceQuestionId":"424480","t":"pen-m10","moduleId":"pen-m10","q":"Ao ser parado numa blitz, Tício, em razão de seus antecedentes criminais, apresentou aos policiais a carteira de identidade de Élvio, na qual havia inserido a sua fotografia. A conduta de Tício caracterizou o delito de","o":["falsificação de documento particular.","falsidade ideológica.","falsificação de documento público.","falsa identidade.","uso de documento falso."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 10: Crimes contra a fé pública.","r":"FCC - NeR (TJ AP)/TJ AP/Outorga de Delegações de Serviços de Notas e de Registros/2011 • TEC 424480","source":"FCC - NeR (TJ AP)/TJ AP/Outorga de Delegações de Serviços de Notas e de Registros/2011","subject":"Direito Penal - Falsa Identidade (arts. 307 a 308 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/424480","year":2011,"caderno":5,"classificationReason":"Crime situado no Título dos crimes contra a fé pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"});
